glsl:
vec4 effect(vec2 uv) {
  vec4 c = getColor(uv);
  vec3 add = vec3(0.0);
  for (int i = 0; i < 14; i++) {
    float fi = float(i);
    vec2 p = vec2(hash(vec2(fi, 1.0)), hash(vec2(fi, 2.0)));
    p += vec2(sin(uTime * 0.25 + fi), cos(uTime * 0.2 + fi * 1.3)) * 0.05;
    float r = 0.04 + 0.07 * hash(vec2(fi, 3.0));
    vec2 d = (uv - p) * vec2(uRatio, 1.0);
    float disk = smoothstep(r, r * 0.8, length(d));
    vec3 col = mix(vec3(1.0, 0.75, 0.4), vec3(1.0, 0.45, 0.6), hash(vec2(fi, 4.0)));
    add += col * disk * 0.35;
  }
  return vec4(1.0 - (1.0 - c.rgb) * (1.0 - add * uAmount), c.a);
}
